<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Donation; use Illuminate\Http\Request; use Illuminate\Support\Facades\{DB,Storage};
class DonationController extends Controller { public function slip(Donation $donation){abort_unless(Storage::disk('local')->exists($donation->slip_path),404);return Storage::disk('local')->response($donation->slip_path);} public function index(Request $r){$donations=Donation::with('channel')->when($r->status,fn($q,$v)=>$q->where('status',$v))->latest()->paginate(25)->withQueryString();return view('admin.donations.index',compact('donations'));} public function show(Donation $donation){$donation->load('channel','reviewer');return view('admin.donations.show',compact('donation'));} public function approve(Request $r,Donation $donation){DB::transaction(fn()=>$donation->lockForUpdate()->update(['status'=>'confirmed','reviewed_by'=>$r->user()->id,'reviewed_at'=>now(),'rejection_reason'=>null]));return redirect()->route('admin.donations.index')->with('success','လှူဒါန်းမှုကို အတည်ပြုပြီးပါပြီ။');} public function reject(Request $r,Donation $donation){$data=$r->validate(['rejection_reason'=>'required|string|max:255']);$donation->update($data+['status'=>'rejected','reviewed_by'=>$r->user()->id,'reviewed_at'=>now()]);return redirect()->route('admin.donations.index')->with('success','လှူဒါန်းမှုကို ပယ်ချပြီးပါပြီ။');} }
